// TestQA_AssetEmptyNameGuard404 proves the name=="" guard in serveAsset: a
// request to /assets/ (nothing after the prefix) returns 404 and does NOT fall
// through to the SPA index fallback. This is distinct from /assets/missing.js
// (which 404s via embed.FS ReadFile error) — it covers the empty-name branch.
func TestQA_AssetEmptyNameGuard404(t *testing.T) {
	h := web.Handler(nil, web.Options{})
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/assets/", nil))
	if rec.Code != http.StatusNotFound {
		t.Fatalf("/assets/ (empty name): status = %d, want 404 (name==\"\" guard)", rec.Code)
	}
	// Must NOT serve the SPA index.html (the empty-name guard fires before any
	// fallback; body is http.NotFound's "404 page not found", not the SPA shell).
	if strings.Contains(rec.Body.String(), `<script src="/assets/app.js">`) {
		t.Errorf("/assets/ leaked the SPA index.html (empty-name guard did not fire before fallback); body=%q", rec.Body.String())
	}
}

// TestQA_BuildGateNodeFreeDryRun is the load-bearing AC-7 invariant: the Go
// build-gate recipes (build/check/test/lint) NEVER invoke the JS/swag toolchain.
// It asserts the DRY-RUN recipe text (`make -n`) contains none of
// node/npm/swag/web-build — independent of whether the host has node installed
// (the host running this HAS node, so `make build` would pass either way; only
// the dry-run proves the recipe is node-free). Positive checks (recipe contains
// the expected go build/check.sh/go test/golangci-lint command) prevent an
// empty-recipe tautology. Skipped under -short or if make is absent.
func TestQA_BuildGateNodeFreeDryRun(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping node-free dry-run probe in -short mode")
	}
	if _, err := exec.LookPath("make"); err != nil {
		t.Skip("make not on PATH — skipping node-free dry-run probe")
	}
	wantCmd := map[string]string{
		"build": "go build",
		"check": "check.sh",
		"test":  "go test",
		"lint":  "golangci-lint",
	}
	for _, target := range []string{"build", "check", "test", "lint"} {
		out, err := exec.Command("make", "-n", target).CombinedOutput()
		if err != nil {
			t.Fatalf("make -n %s: %v (output: %s)", target, err, out)
		}
		// Positive: the recipe must still do the expected Go-gate work (guards
		// against an empty-recipe false pass).
		if !strings.Contains(string(out), wantCmd[target]) {
			t.Errorf("make -n %s recipe missing expected %q; recipe=%q", target, wantCmd[target], out)
		}
		// Negative: the recipe must not invoke the JS/swag toolchain.
		for _, forbidden := range []string{"node", "npm", "swag", "web-build"} {
			if strings.Contains(string(out), forbidden) {
				t.Errorf("make -n %s recipe invokes %q (AC-7 node-free gate breached); recipe=%q", target, forbidden, out)
			}
		}
	}
}
